const mediaUi=createMediaController({api,mutate,auth,notice,onAssigned:async targets=>{
  if(currentScenario&&targets.some(t=>t.scope==='scenario'&&t.scopeId===currentScenario.id))currentScenario=mediaEditorSnapshot(currentScenario,await api('scenario',{scenarioId:currentScenario.id}));
  if(currentSession&&targets.some(t=>t.scope==='session'&&t.scopeId===currentSession.id))currentSession=mediaEditorSnapshot(currentSession,await api('session',{sessionId:currentSession.id}));
  for(const f of document.querySelectorAll('[data-form][data-parent]')){const p=f.dataset.scope==='session'?currentSession:currentScenario;if(p?.id===f.dataset.parent&&p.revision===Number(f.dataset.revision)+1)f.dataset.revision=p.revision;}
  for(const f of document.querySelectorAll('[data-form="announcementEditor"]')){const d=await api('sessionAnnouncements',{sessionId:f.dataset.sid});const a=d.announcements.find(a=>a.id===f.dataset.id);if(a&&mediaEditorSnapshot({id:f.dataset.id,revision:Number(f.dataset.revision)},a)===a)f.dataset.revision=a.revision;}
  for(const n of document.querySelectorAll('[data-media-request]')){n.removeAttribute('data-media-loaded');n.replaceWith(n.cloneNode(true));}
  if(!dialog.open&&!location.hash.startsWith('#/media/'))await route();
}});
