const masterUi=createMasterController({api,mutate,notice,getContext:scope=>scope==='session'?currentSession:currentScenario,onApplied:async(scope,id)=>{if(location.hash===`#/${scope}/${id}`)await route();else location.hash=`#/${scope}/${id}`;}});
async function campaignPage(id){const render=pageRenderer(),d=await api('campaign',{campaignId:id});render(campaignUi.page(d));}
async function continueCampaignBuild(campaignId,buildId,expected){
 let d;do {if(expected!==routeVersion)return;d=await mutate('advanceCampaignEpisode',{campaignId,buildId});if(expected!==routeVersion)return;notice(`Préparation de l’épisode : ${d.cursor} / ${d.pages}.`);}while(d.status!=='READY');
 location.hash=`#/session/${d.id}`;notice('Épisode prêt. Les acquis ont été conservés.');
}
const healthUi=createHealthUi({button,link});
async function dashboard(){const render=pageRenderer();
  if(!auth.currentUser){render(accessHomeHtml(loginPanel()));return;}
  if(!identity?.organizer){render(`<section class="narrow"><p class="eyebrow">Bienvenue</p><h1>Prêt à entrer en jeu ?</h1><p class="lead">Ouvrez le lien de votre session pour retrouver votre inscription et votre personnage.</p><div class="panel"><p>Vous êtes connecté avec <strong>${esc(auth.currentUser.email)}</strong>.</p><p class="muted">Le même compte vous accompagne de l’inscription au briefing.</p></div></section>`);return;}
  const d=await api('dashboard');render(`<div class="hero"><div><p class="eyebrow">Espace organisateur</p><h1>Aux commandes de<br>votre prochaine histoire.</h1><p class="lead">Des scénarios réutilisables. Des parties indépendantes ou des campagnes.<br>Un rôle et les bonnes informations pour chaque joueur.</p></div><div class="hero-tools">${identity.admin?button('+ Préparation SPACE OUTLAWS','newSpaceOutlawsPreparation','','primary')+mediaLink('owner','')+archiveImportButton()+button('+ Nouveau scénario','newScenario','','primary'):''}</div></div><div class="stats"><div class="stat"><strong>${d.scenarios.length}</strong><span>Scénarios</span></div><div class="stat"><strong>${d.sessions.length}</strong><span>Sessions</span></div><div class="stat"><strong>${d.sessions.reduce((n,s)=>n+s.accepted,0)}</strong><span>Inscriptions acceptées</span></div></div>${centralUi.dashboard(d.centralCampaigns)}${campaignUi.dashboard(d.campaigns??[])}<div class="section-head"><h2>Vos sessions</h2><span class="muted">L’aventure en préparation</span></div><div class="grid">${d.sessions.map(s=>`<article class="card"><div class="row spread">${pill(s.stage)}<span class="pill ${s.registrationOpen?'green':''}">${s.registrationOpen?'Inscriptions ouvertes':'Accueil fermé'}</span></div><h3>${esc(s.title)}</h3>${pill(s.role)}<p class="muted">${esc(s.date||'Date à définir')} · ${esc(s.place||'Lieu à définir')}<br>${s.accepted} / ${s.capacity} participants</p>${link('Gérer la session →',`session/${s.id}`,'button quiet')}</article>`).join('')||'<div class="empty">Votre première session apparaîtra ici.<br>Commencez par créer un scénario.</div>'}</div>${identity.admin?`<div class="section-head"><h2>Bibliothèque de scénarios</h2></div><div class="grid">${d.scenarios.map(s=>`<article class="card"><p class="eyebrow">Scénario</p><h3>${esc(s.title)}</h3><p class="muted">${esc(s.summary||'Une nouvelle histoire à écrire.')}</p>${link('Écrire & préparer →',`scenario/${s.id}`,'button quiet')}</article>`).join('')||'<div class="empty">Aucun scénario pour le moment.</div>'}</div>`:''}`);
}
let currentScenario,currentSession,editingCharacter;
const readCurrent=(r,c)=>!!r?.briefingReadAt && r.briefingReadRevision===(c?.contentRevision??1);
async function scenarioPage(id){const render=pageRenderer();
  const s=await api('scenario',{scenarioId:id});if(!render.current())return; s.masterWorkspace=await api('masterWorkspace',{scenarioId:id});if(!render.current())return;currentScenario=s;
  render(`${breadcrumbs(s.title)}<div class="hero"><div><p class="eyebrow">Atelier de scénario</p><h1>${esc(s.title)}</h1>${mediaLink('scenario',s.id)}${archiveExportButton()}<p class="lead">${esc(s.summary)}</p></div>${button('+ Ajouter un personnage','editCharacter','','primary')}</div>${workshopDashboard(s,'scenario')}<section id="workshop-personnages" class="workshop-section" tabindex="-1" aria-label="Personnages"><div class="columns"><section class="panel"><div class="section-head"><h2>Personnages</h2><span class="muted">${s.characters.length} fiches</span></div>${s.characters.length?`<div class="table-scroll"><table><thead><tr><th>Identité publique</th><th>Publication</th><th></th></tr></thead><tbody>${s.characters.map(c=>`<tr><td><strong>${esc(c.public.displayName)}</strong><br><small>${esc(c.public.profession)}</small></td><td>${pill(c.publicationState)}</td><td>${button('Modifier','editCharacter',`data-id="${c.id}"`,'small quiet')}${button('Compétences','assignAbilities',`data-id="${c.id}" data-scope="scenario"`,'small quiet')}${button('Matériel de départ','inventorySeedForm',`data-id="${c.id}"`,'small quiet')}${button('Versions','characterHistory',`data-id="${c.id}" data-scope="scenario"`,'small quiet')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Ajoutez les premières identités et leurs informations privées.</p>'}</section><section class="stack"><div class="panel gold"><p class="eyebrow">Figer une version</p><h2>Une base stable pour chaque session.</h2><p class="muted">La version conserve l’état actuel de vos fiches, y compris leur niveau de publication. Les modifications suivantes du scénario ne changent pas les sessions déjà créées.</p>${button('Créer une version','publishScenario',s.characters.length?'':'disabled','primary')}</div><div class="panel"><h2>Versions disponibles</h2>${s.versions.sort((a,b)=>b.createdAt-a.createdAt).map((v,i)=>`<div class="row spread"><p><strong>Version du ${new Date(v.createdAt).toLocaleString('fr-FR')}</strong><br><small>${v.characterCount} personnages · révision ${v.sourceRevision}</small></p>${button('Créer une session','newSession',`data-id="${v.id}"`,'small')}</div>`).join('')||'<p class="muted">Aucune version figée.</p>'}</div></section></div>${personAdminLink(s.id,'scenario')}${groupUi.adminPanel(s,'scenario')}${abilityUi.adminPanel(s,'scenario')}${healthUi.admin(s,'scenario')}${apUi.admin(s,'scenario')}</section>
  ${workshopSection('communication','<p>Les objectifs se modifient dans les fiches des personnages ou dans le Master Objectifs. Les annonces, contrats et primes se gèrent dans chaque session. Les rendez-vous ne sont pas encore disponibles.</p><button type="button" class="quiet" data-workshop-jump="personnages">Ouvrir les fiches et leurs objectifs</button>','scenario')}
  ${workshopSection('magasins',inventoryUi.admin(s,'scenario')+'<p>Ce catalogue est commun à tous les échanges. Les boutiques avec stock, caisse et QR ne sont pas encore disponibles.</p>','scenario')}
  ${workshopSection('spatioport','<p>Préparez les vaisseaux et les routes avec le Master de ce module. Les cargaisons, réservoirs et voyages se pilotent ensuite dans la régie de chaque session.</p><button type="button" class="quiet" data-master-action="open" data-scope="scenario" data-module="spatioport">Importer vaisseaux et routes</button>','scenario')}
  ${workshopSection('economie',tariffMasterLink(s,'scenario')+logisticsUi.scenario(s)+economyUi.admin(s,'scenario')+collectiveUi.admin(s,'scenario'),'scenario')}
  ${workshopSection('informations',knowledgeUi.adminPanel(s,'scenario')+fieldAdminLink(s.id,'scenario'),'scenario')}
  ${masterPanel(s,'scenario')}`);
}
function narrativeRow(kind,item={},scope='scenario') {
  const id=item.id??crypto.randomUUID(),isRelation=kind==='relations';
  const characters=(scope==='session'?currentSession:currentScenario).characters;
  return `<fieldset class="narrative-item" data-kind="${kind}" data-id="${esc(id)}"><legend>${isRelation?'Relation orientée':'Objectif narratif'}</legend><label>${isRelation?'Nom du contact tel que le joueur le connaît':'Titre'}<input data-field="title" value="${esc(item.title)}" maxlength="200" required></label><label>Texte destiné à ce joueur<textarea data-field="description" maxlength="10000">${esc(item.description)}</textarea></label>${isRelation?`<label>Personnage lié · référence réservée au MJ<select data-field="targetId"><option value="">Contact libre, sans lien technique</option>${characters.filter(c=>c.id!==editingCharacter?.id).map(c=>`<option value="${c.id}" ${c.id===item.targetId?'selected':''}>${esc(c.public.displayName)}</option>`).join('')}</select></label>`:''}<label>Notes MJ<textarea data-field="gmNotes" maxlength="4000">${esc(item.gmNotes)}</textarea></label><label class="check"><input type="checkbox" data-field="published" ${item.published?'checked':''}>Publier cet élément avec la fiche</label><button type="button" class="quiet small danger" data-action="removeNarrative">Retirer cet élément</button></fieldset>`;
}
function characterForm(id,scope='scenario'){
  const c=(scope==='session'?currentSession:currentScenario).characters.find(c=>c.id===id);editingCharacter=c;
  modal(`<p class="eyebrow">${scope==='session'?'Fiche de session':'Atelier de scénario'}</p><h2>${c?'Modifier':'Créer'} un personnage</h2>${c&&scope==='session'?link('Gérer ses groupes',`group-admin/${currentSession.id}/${c.id}`,'button quiet'):''}${c?mediaPickerButton(scope,(scope==='session'?currentSession:currentScenario).id,'character',c.id,'portrait','Portrait public')+mediaPickerButton(scope,(scope==='session'?currentSession:currentScenario).id,'character',c.id,'private','Image de fiche privée'):'<p>Enregistrez la fiche pour lui attribuer des images.</p>'}<form data-form="character" data-scope="${scope}" data-id="${esc(id||'')}"><div class="two">${input('Nom public','displayName',c?.public.displayName,'text',true)}${input('Profession / couverture','profession',c?.public.profession)}${scope==='session'?`<p>Nature : ${esc(natureLabel(c?.nature))} · conservée depuis la création.</p>`:`<label>Nature<select name="nature"><option value="">Non renseignée (historique)</option>${Object.entries(characterNatures).map(([key,label])=>`<option value="${key}" ${c?.nature===key?'selected':''}>${label}</option>`).join('')}</select></label>`}<div class="full">${textarea('Description publique','description',c?.public.description,'Visible depuis le badge, sans coordonnées du participant.')}</div><div class="full">${textarea('Histoire personnelle','biography',c?.biography)}${textarea('Secrets du joueur','playerSecrets',c?.playerSecrets)}${textarea('Consignes de jeu et de costume','roleplay',c?.roleplay)}${textarea('Notes réservées au MJ','gmNotes',c?.gmNotes,'Ces notes ne sont jamais transmises au joueur, même dans l’aperçu.')}
  <h3>Relations privées</h3><p class="muted">Chaque relation appartient uniquement à cette fiche. Le personnage lié ne reçoit rien. Utilisez un alias dans le titre si sa véritable identité doit rester secrète.</p><div data-list="relations">${(c?.relations??[]).map(x=>narrativeRow('relations',x,scope)).join('')}</div><button type="button" class="quiet" data-action="addNarrative" data-kind="relations">+ Ajouter une relation</button>
  <h3>Objectifs narratifs</h3><p class="muted">Consignes personnelles, sans validation automatique ni récompense. Chaque élément peut rester non publié.</p><div data-list="objectives">${(c?.objectives??[]).map(x=>narrativeRow('objectives',x,scope)).join('')}</div><button type="button" class="quiet" data-action="addNarrative" data-kind="objectives">+ Ajouter un objectif</button>
  <label>État de publication<select name="publicationState">${['DRAFT','READY','PUBLISHED'].map(s=>`<option value="${s}" ${c?.publicationState===s?'selected':''}>${labels[s]}</option>`).join('')}</select><small>Les éléments cochés deviennent visibles lorsque la fiche est publiée et le briefing ouvert.</small></label>${scope==='session'?input('Motif de cette modification','reason','','text',true):''}</div></div><button class="primary" type="submit">Enregistrer la fiche</button></form>`);
}
function abilityRows(form){return [...form.querySelectorAll('[data-ability-row]')].filter(row=>row.querySelector('[data-ability-selected]').checked).map(row=>({skillId:row.dataset.abilityRow,level:Number(row.querySelector('[data-ability-level]').value)}));}
function collectNarrative(form,kind){return [...form.querySelectorAll(`[data-list="${kind}"] fieldset`)].map(row=>{
  const item={id:row.dataset.id};
  for(const field of row.querySelectorAll('[data-field]'))item[field.dataset.field]=field.type==='checkbox'?field.checked:field.value;
  if(kind==='objectives')item.steps=editingCharacter?.objectives?.find(x=>x.id===item.id)?.steps??[];
  return item;
});}
function staffPanel(s){const p=s.permissions;return p.staff?`<section class="panel"><div class="section-head"><div><p class="eyebrow">Délégations par session</p><h2>Votre équipe</h2></div>${button('+ Ajouter une personne','editStaff','','quiet')}</div><p class="muted">Le rôle Accueil gère les participants. Le rôle MJ accède aussi aux secrets et au pilotage du jeu.</p>${s.staff.length?s.staff.map(g=>`<div class="row spread team-row"><div><strong>${esc(g.email)}</strong><br>${pill(g.role)} <span class="muted">${g.active?'Active':'Révoquée'}</span></div>${button('Modifier les droits','editStaff',`data-email="${esc(g.email)}"`,'small quiet')}</div>`).join(''):'<p class="empty">Vous gérez cette session seul pour le moment.</p>'}</section>`:'';}
function staffForm(email){const g=currentSession.staff.find(x=>x.email===email);
  modal(`<p class="eyebrow">Équipe · cette session uniquement</p><h2>${g?'Modifier une délégation':'Ajouter une personne'}</h2><form data-form="staff">${g?`<label>Compte Google<input name="email" type="email" value="${esc(g.email)}" readonly></label>`:input('Adresse du compte Google','email','','email',true)}<label>Rôle<select name="role"><option value="RECEPTION" ${g?.role==='RECEPTION'?'selected':''}>Accueil</option><option value="MJ" ${g?.role==='MJ'?'selected':''}>MJ</option></select></label>${currentSession.preparationKind?'<p class="muted">Dans cette préparation, le MJ peut modifier les informations pratiques ; l’Accueil peut les consulter. Ces rôles de session ne donnent aucun droit de publication du Master central.</p>':'<p class="muted"><strong>Accueil :</strong> inscriptions, réponses privées, attributions et invitations. Aucun secret de personnage.<br><strong>MJ :</strong> mêmes droits, plus les fiches complètes, leurs historiques et le pilotage du jeu.</p>'}<label class="check"><input name="active" type="checkbox" ${!g||g.active?'checked':''}>Délégation active</label>${input('Motif','reason','','text',true)}<p class="muted">Cette autorisation prend effet dès l’enregistrement. Aucun courriel n’est envoyé. Seul le propriétaire peut gérer l’équipe.</p><button class="primary" type="submit">Enregistrer les droits</button></form>`);
}
function sessionForm(versionId){modal(`<p class="eyebrow">Nouvelle session</p><h2>Les informations de votre événement</h2><form data-form="session" data-version="${versionId}"><label>Mode de jeu<select name="mode"><option value="INDEPENDENT">Partie indépendante</option><option value="CAMPAIGN">Premier épisode d’une nouvelle campagne</option></select></label><label>Nom de la campagne · si ce mode est choisi<input name="campaignTitle" maxlength="150" value="${esc(currentScenario.title)}"></label><p>Pour continuer une campagne existante, ouvrez-la depuis le tableau de bord.</p><div class="two">${input('Titre','title',currentScenario.title,'text',true)}${input('Capacité','capacity','','number',true)}${input('Date','date','','date')}${input('Horaires','time')}${input('Lieu','place')}<div class="full">${textarea('Conditions pratiques','practical')}${textarea('Information sur les données personnelles','privacy','','Précisez l’usage, les organisateurs destinataires, la durée de conservation et le contact pour correction ou suppression. Ce texte sera visible avant l’inscription.')}<label>Questions supplémentaires, une par ligne<textarea name="fields" placeholder="Préférences de jeu&#10;Disponibilités"></textarea><small>Facultatives. Ne demandez que les informations utiles à votre accueil.</small></label></div></div><button class="primary">Créer la session</button></form>`);}
async function sessionPage(id){const render=pageRenderer();
  const s=await api('session',{sessionId:id});if(!render.current())return;if(s.preparationKind){currentSession=s;render(preparationUi.page(s,staffPanel(s)));return;}if(s.role==='OWNER')s.masterWorkspace=await api('masterWorkspace',{sessionId:id});if(!render.current())return;currentSession=s;
  const p=s.permissions;
  const transitions={PREPARATION:[['BRIEFING','Ouvrir le briefing']],BRIEFING:[['EN_JEU','Démarrer le jeu']],EN_JEU:[['PAUSE','Mettre en pause'],['FINISHED','Terminer le jeu']],PAUSE:[['EN_JEU','Reprendre le jeu'],['FINISHED','Terminer le jeu']],FINISHED:s.campaignId?[]:[['ARCHIVED','Archiver']],ARCHIVED:[]};
  render(`${breadcrumbs(s.title)}<div class="hero"><div><p class="eyebrow">Régie de session · ${esc(labels[s.role])}</p>${p.content?mediaLink('session',s.id)+link('Régie des groupes',`group-admin/${s.id}`,'button quiet'):''}<h1>${esc(s.title)}</h1><div class="row">${pill(s.stage)}<span class="pill ${s.registrationOpen?'green':''}">${s.registrationOpen?'Inscriptions ouvertes':'Inscriptions fermées'}</span></div></div>${button('Partager l’inscription','shareSession','','primary')}</div>
  ${workshopDashboard(s,'session')}${p.content?campaignUi.panel(s)+masterPanel(s,'session'):''}<div class="stats"><div class="stat"><strong>${s.accepted}<small> / ${s.capacity}</small></strong><span>Places acceptées</span></div><div class="stat"><strong>${s.registrations.filter(r=>r.status==='WAITLISTED').length}</strong><span>En attente</span></div><div class="stat"><strong>${s.characters.filter(c=>c.assignedUid).length}<small> / ${s.characters.length}</small></strong><span>Personnages attribués</span></div></div>
  <section class="panel row spread"><div><strong>Accueil & rythme de jeu</strong><p class="muted">Les inscriptions et l’horloge de jeu se pilotent séparément.</p></div><div class="row">${!['FINISHED','ARCHIVED'].includes(s.stage)?button(s.registrationOpen?'Fermer les inscriptions':'Ouvrir les inscriptions','toggleRegistration','','quiet'):''}${p.rhythm?transitions[s.stage].map(([st,label])=>button(label,'setStage',`data-stage="${st}"`,st==='FINISHED'?'danger':'')).join(''):''}</div></section>
  ${staffPanel(s)}
  <div class="section-head"><h2>Participants & attributions</h2>${button('Actualiser','refresh','','quiet small')}</div><label class="search-label">Rechercher un participant ou un personnage<input type="search" data-filter="session" placeholder="Nom, adresse ou identité de jeu"></label>
  <section class="panel"><div class="table-scroll"><table><thead><tr><th>Participant</th><th>Inscription</th><th>Personnage</th><th>Accès & préparation</th></tr></thead><tbody>${s.registrations.map(r=>{const c=s.characters.find(c=>c.id===r.characterId);return `<tr data-search="${esc(`${r.name} ${r.email} ${c?.public.displayName??''}`.toLowerCase())}"><td><strong>${esc(r.name)}</strong><br><small>${esc(r.email)}</small><br>${button('Réponses privées','answers',`data-uid="${esc(r.uid)}"`,'quiet small')}</td><td>${pill(r.status)}<br>${button('Changer le statut','changeStatus',`data-uid="${esc(r.uid)}"`,'quiet small')}</td><td>${esc(c?.public.displayName||'Non attribué')}${!c&&r.previousCharacterId?`<br><small>Rôle précédent : ${esc(s.characters.find(x=>x.id===r.previousCharacterId)?.public.displayName)}</small>`:''}<br>${r.status==='ACCEPTED'?button('Attribuer / remplacer','assign',`data-uid="${esc(r.uid)}"`,'quiet small'):''}</td><td><span class="pill ${r.accessActive?'green':''}">${r.accessActive?'Accès activé':'Accès inactif'}</span><p><small>${readCurrent(r,c)?'Fiche actuelle lue':r.briefingReadAt?'Fiche modifiée · lecture à confirmer':'Lecture non confirmée'}</small></p>${r.characterId?`<div class="row">${button('Invitation','invite',`data-uid="${esc(r.uid)}"`,'small')}${button('Révoquer','revoke',`data-uid="${esc(r.uid)}"`,'small danger')}</div>`:''}</td></tr>`;}).join('')||'<tr><td colspan="4"><p class="empty">Ouvrez les inscriptions et partagez le lien de cette session.</p></td></tr>'}</tbody></table></div></section>
  ${p.content?workshopSection('communication',`<p>Publiez des petites annonces et gérez les réponses privées.</p>${link('Gérer les petites annonces',`announcements-admin/${s.id}`,'button primary')}${link('Contrats et preuves',`contracts-admin/${s.id}`,'button quiet')}${link('Primes ouvertes',`bounties-admin/${s.id}`,'button quiet')}<p>Les rendez-vous physiques ne sont pas encore disponibles.</p>`,'session')+workshopSection('magasins',inventoryUi.admin(s,'session')+'<p>Le catalogue et le marché sont disponibles ; les boutiques avec stock, caisse et QR restent à développer.</p>','session')+workshopSection('spatioport',link('Vaisseaux, routes et cargaisons',`cargo-admin/${s.id}`,'button primary'),'session')+workshopSection('economie',tariffMasterLink(s,'session')+link('Entrepôts et recharges',`warehouses-admin/${s.id}`,'button quiet')+link('Cours et événements économiques',`prices-admin/${s.id}`,'button quiet')+economyUi.admin(s,'session')+collectiveUi.admin(s,'session'),'session')+workshopSection('informations',knowledgeUi.adminPanel(s,'session')+fieldAdminLink(s.id,'session'),'session'):''}
  ${p.content?'<section id="workshop-personnages" class="workshop-section" tabindex="-1" aria-label="Personnages">'+groupUi.adminPanel(s,'session')+abilityUi.adminPanel(s,'session')+healthUi.admin(s,'session')+apUi.admin(s,'session')+personAdminLink(s.id,'session'):''}
  ${p.content?`<div class="section-head"><h2>Fiches de la session</h2><span class="muted">Copie indépendante du scénario</span></div><div class="grid">${s.characters.map(c=>`<article class="card" data-search="${esc(`${c.public.displayName} ${c.public.profession}`.toLowerCase())}">${pill(c.publicationState)}<h3>${esc(c.public.displayName)}</h3><p class="muted">${esc(c.public.profession)}</p><div class="row">${button('Modifier la fiche','editCharacter',`data-id="${c.id}" data-scope="session"`,'small')}${button('Compétences','assignAbilities',`data-id="${c.id}" data-scope="session"`,'small')}${button('Attribuer un objet','grantItemForm',`data-id="${c.id}"`,'small')}${button('Aperçu du sac','previewInventory',`data-id="${c.id}"`,'quiet small')}${s.healthRules?.enabled?button('PV / correction','healthCorrection',`data-id="${c.id}"`,'small'):''}${button('Voir comme le joueur','preview',`data-id="${c.id}"`,'small')}${button('Versions publiées','characterHistory',`data-id="${c.id}" data-scope="session"`,'quiet small')}${button('Badge public','badge',`data-id="${c.id}"`,'quiet small')}</div></article>`).join('')}</div><details class="panel"><summary>Journal des dernières opérations</summary>${s.audit.map(a=>`<p class="muted">${new Date(a.at).toLocaleString('fr-FR')} — ${esc(a.action)}${a.reason?` · ${esc(a.reason)}`:''}<br><small>Auteur : ${esc(a.actorUid)}${a.characterId?` · Personnage : ${esc(a.characterId)}`:''}${a.beforeRevision?` · Fiche ${a.beforeRevision} → ${a.afterRevision}`:''}</small></p>`).join('')}</details></section>`:'<p class="muted">Votre rôle Accueil donne accès aux inscriptions et aux attributions. Les fiches privées sont réservées aux MJ.</p>'}`);
  if(s.campaignSealed)for(const b of app.querySelectorAll('button[data-action]'))if(!['refresh','answers','characterHistory','groupHistory','walletHistory','knowledgeHistory','abilityHistory','itemHistory','apHistory'].includes(b.dataset.action)&&!(b.dataset.action==='editStaff'&&b.dataset.email))b.disabled=true;
}
async function joinPage(id){const render=pageRenderer();
  const s=await api('publicSession',{sessionId:id}); let own=null;
  if(auth.currentUser) own=await api('mySession',{sessionId:id});
  render(`<div class="narrow"><p class="eyebrow">Votre prochaine aventure</p><h1>${esc(s.title)}</h1><p class="lead">${esc(s.summary)}</p><div class="steps"><span class="active">01 · Inscription</span><span>02 · Attribution</span><span>03 · Briefing</span></div><section class="panel"><div class="row spread"><h2>Informations pratiques</h2><span class="pill ${s.registrationOpen?'green':''}">${s.registrationOpen?'Inscriptions ouvertes':'Inscriptions fermées'}</span></div><p>${esc(s.date||'Date à préciser')} · ${esc(s.time)}<br>${esc(s.place||'Lieu à préciser')}</p><div class="prose">${esc(s.practical)}</div><p class="muted">${s.available} place(s) disponible(s) sur ${s.capacity}. ${s.available===0?'Les nouvelles demandes rejoignent la liste d’attente.':''}</p></section><div class="section-head"><h2>Votre inscription</h2></div>${own?.registration?`<section class="panel gold">${pill(own.registration.status)}<h2>Bienvenue, ${esc(own.registration.name)}.</h2><p>Votre inscription est enregistrée. ${own.registration.status==='ACCEPTED'?'L’organisateur prépare votre attribution.':'Retrouvez ici son statut à tout moment.'}</p><div class="row">${link('Ouvrir mon espace joueur',`play/${id}`,'button primary')}${button('Annuler mon inscription','cancel',`data-id="${id}"`,'quiet')}</div></section>`:!auth.currentUser?loginPanel():s.registrationOpen?`<form class="panel" data-form="register" data-id="${id}">${input('Nom ou nom d’usage','name',auth.currentUser.displayName,'text',true)}<p class="muted">Votre compte ${esc(auth.currentUser.email)} permet de retrouver cette inscription.</p>${s.fields.map(f=>`<label>${esc(f.label)}<textarea name="field_${f.id}" maxlength="2000" ${f.required?'required':''}></textarea></label>`).join('')}<h3>Vos données</h3><p class="prose muted">${esc(s.privacy)}</p><button class="primary">${s.available?'Confirmer mon inscription':'Rejoindre la liste d’attente'}</button></form>`:'<p class="empty">Les inscriptions sont actuellement fermées.</p>'}<details><summary>Utilisation de vos données</summary><p class="prose muted">${esc(s.privacy)}</p></details></div>`);
}
async function playerPage(id){const render=pageRenderer();
  if(!auth.currentUser){render(`<div class="narrow"><p class="eyebrow">Espace joueur</p><h1>Retrouvez votre personnage.</h1>${loginPanel()}</div>`);return;}
  const d=currentPlayer??await api('mySession',{sessionId:id});
  render(`<div class="narrow">${d.character?characterView(d.character,{mode:'player',scope:'session',scopeId:id,kind:'character',id:d.character.id},false):`<section class="panel"><p class="eyebrow">Espace joueur</p><h1>${esc(d.session.title)}</h1><p>${esc(errors[d.reason]||'Votre organisateur prépare votre personnage. Vous retrouverez votre fiche ici après attribution et activation de votre invitation.')}</p>${d.registration?pill(d.registration.status):link('M’inscrire',`join/${id}`,'button primary')}</section>`}${d.character?`<div class="section-head">${readCurrent(d.registration,d.character)?'<span class="pill green">Fiche actuelle lue</span>':button('J’ai lu mon briefing','readBriefing',`data-id="${id}"`,'primary')}</div>${d.health?`<details class="panel"><summary>Mon état et déclaration de dégâts</summary>${healthUi.quick(d.health,id)}</details>`:''}`:''}</div>`);
}
