async function announcementsPage(sid,id,mode='board'){const render=pageRenderer();if(!auth.currentUser){render(`<div class="narrow"><h1>Petites annonces</h1><p>Connectez-vous pour consulter les missions et vos échanges privés.</p>${loginPanel()}</div>`);return;}let content;
  if(mode==='admin'){const d=await api('sessionAnnouncements',{sessionId:sid});content=announcementUi.admin(d);}
  else if(mode==='thread'){const d=await api('applicationDetail',{sessionId:sid,applicationId:id});content=announcementUi.thread(d);}
  else if(id){const d=await api('announcementDetail',{sessionId:sid,announcementId:id});content=announcementUi.detail(d);}
  else {const [d,mine]=await Promise.all([api('announcements',{sessionId:sid}),api('myApplications',{sessionId:sid})]);content=announcementUi.board(d,mine);}
  render(`<div class="narrow"><nav class="breadcrumb">${mode==='admin'?link('Régie de session',`session/${sid}`,''):link('Terminal',`terminal/${sid}`,'')+link('Petites annonces',`missions/${sid}`,'')}</nav>${content}</div>`);
}
function filterAnnouncements(root){const term=root.querySelector('[data-announcement-search]').value,category=root.querySelector('[data-announcement-category]').value;let count=0;for(const row of root.querySelectorAll('[data-announcement-row]')){row.hidden=!announcementMatches(JSON.parse(row.dataset.announcementValue),term,category);if(!row.hidden)count++;}root.querySelector('[data-announcement-empty]').hidden=count>0;}
async function cargoPage(sid,id=null,mode='cargo'){
 const render=pageRenderer(),action=mode==='admin'?'cargoAdmin':mode==='hold'?'shipHold':mode==='transfer'?'cargoTransfer':id?'cargoLot':'myCargo';
 const d=await api(action,{sessionId:sid,...(id?{[mode==='hold'?'shipId':mode==='transfer'?'transferId':'lotId']:id}:{})});
 if(mode==='hold')d.navigation=await api('shipNavigation',{sessionId:sid,shipId:id});
 const accounts=mode==='transfer'&&d.canReceive&&d.transfer.clearance?.total>0?(await api('myAccounts',{sessionId:sid})).accounts:[];
 render(`<div class="narrow">${mode==='admin'?cargoUi.admin(d):mode==='hold'?cargoUi.hold(d):mode==='transfer'?cargoUi.transfer(d,accounts):id?cargoUi.lot(d):cargoUi.overview(d)}</div>`);
}
async function warehousesPage(sid,wid=null,admin=false){const render=pageRenderer();const d=await api(admin?'warehouseAdmin':wid?'warehouseDetail':'warehouses',{sessionId:sid,...(wid?{warehouseId:wid}:{})});const accounts=!admin&&wid&&d.canRent?await api('myAccounts',{sessionId:sid}):{accounts:[]};render(`<div class="narrow">${admin?logisticsUi.admin(d):wid?logisticsUi.detail(d,accounts.accounts):logisticsUi.overview(d)}</div>`);}
