function filterMarket(root){const term=root.querySelector('[data-market-search]').value,category=root.querySelector('[data-market-category]').value,scope=root.querySelector('[data-market-scope]').value;let count=0;for(const row of root.querySelectorAll('[data-market-row]')){row.hidden=!marketMatches(JSON.parse(row.dataset.marketValue),term,category,scope);if(!row.hidden)count++;}root.querySelector('[data-market-empty]').hidden=count>0;}
