  const d=await api('myGroup',{sessionId:sid,groupId:gid});
  render(`<div class="narrow"><nav class="breadcrumb">${link('Mon groupe',`groups/${sid}`,'')}<span>/</span><span>${esc(d.group.name)}</span></nav>${groupUi.detail(d)}${groupMissionLink(d)}<details class="panel"><summary>Mes droits dans ce groupe</summary><ul>${Object.entries(permissionLabels).filter(([key])=>d.group.permissions[key]).map(([,label])=>`<li>${esc(label)}</li>`).join('')||'<li>Aucun droit supplémentaire.</li>'}</ul></details>${button('Actualiser','refresh','','quiet small')}</div>`);
