document.addEventListener('input',event=>{
  if(event.target.closest('[data-form="noteEditor"]'))event.target.closest('form').dataset.dirty='true';
  if(event.target.matches('[data-announcement-search]'))filterAnnouncements(event.target.closest('[data-announcement-root]'));
  if(event.target.matches('[data-market-search]'))filterMarket(event.target.closest('[data-market-root]'));
  if(event.target.matches('[data-inventory-search]'))filterInventory(event.target.closest('[data-inventory-root]'));
  if(event.target.matches('[data-note-search]'))filterNotes();
  if(event.target.matches('[data-filter]')){
  const term=event.target.value.toLowerCase().trim();
  for(const row of app.querySelectorAll('[data-search]'))row.hidden=!row.dataset.search.includes(term);
}});
document.addEventListener('change',event=>{
  if(event.target.matches('[data-form="ability"] select[name="kind"]')){const fields=event.target.form.querySelector('[data-healing-fields]');fields.hidden=event.target.value==='PASSIVE';fields.disabled=fields.hidden;}
  if(event.target.matches('[data-form="healthCorrection"] input[name="hp"]')&&Number(event.target.value)===0)event.target.form.elements.outOfCombat.checked=true;
  if(event.target.matches('[data-seed-picked]'))event.target.closest('[data-seed-row]').querySelector('[data-seed-quantity]').disabled=!event.target.checked;
  if(event.target.matches('[data-announcement-category]'))filterAnnouncements(event.target.closest('[data-announcement-root]'));
  if(event.target.matches('[data-market-pricing]')){const f=event.target.closest('form'),indexed=event.target.value==='INDEXED';f.querySelector('[data-fixed-price]').hidden=indexed;f.elements.amount.disabled=indexed;f.elements.amount.required=!indexed;}
  if(event.target.matches('[data-economic-target]'))for(const field of event.target.closest('form').querySelectorAll('[data-economic-fields]')){field.hidden=field.dataset.economicFields!==event.target.value;field.disabled=field.hidden;}
  if(event.target.matches('[data-price-trigger]')){const field=event.target.closest('form').elements.targetId,linked=event.target.value==='INSTALLATION_OFFLINE';field.disabled=!linked;field.required=linked;}
  if(event.target.matches('[data-market-category],[data-market-scope]'))filterMarket(event.target.closest('[data-market-root]'));
  if(event.target.matches('[data-inventory-status],[data-inventory-category]'))filterInventory(event.target.closest('[data-inventory-root]'));
  if(event.target.matches('[data-form="lotCorrection"] input[name="quantity"]')&&Number(event.target.value)===0)event.target.form.elements.status.value='DESTROYED';
  if(event.target.matches('[data-note-state]'))filterNotes();
  if(event.target.matches('[data-knowledge-filter]')){
    const root=event.target.closest('.narrow')??event.target.closest('dialog');
    const kind=root.querySelector('[data-knowledge-filter="kind"]').value,read=root.querySelector('[data-knowledge-filter="read"]').value;
    let visible=0;for(const item of root.querySelectorAll('[data-knowledge-kind]')){item.hidden=!(kind==='ALL'||item.dataset.knowledgeKind===kind)||!(read==='ALL'||item.dataset.knowledgeRead===read);if(!item.hidden)visible++;}
    root.querySelector('[data-knowledge-empty]').hidden=visible>0;
  }

  if(event.target.matches('[data-form="group"] select[name="visibility"]')){
    for(const field of event.target.form.querySelectorAll('[data-member-field="publicAffiliation"]')){field.disabled=event.target.value==='SECRET';if(field.disabled)field.checked=false;}
  }
});
document.addEventListener('click',event=>{if(event.target.closest('a[href]')&&dirtyNote()&&!confirm('Quitter sans enregistrer les modifications de votre note ?'))event.preventDefault();},true);
dialog.addEventListener('cancel',event=>{if(dirtyNote()&&!confirm('Quitter sans enregistrer les modifications de votre note ?'))event.preventDefault();});
dialog.addEventListener('close',()=>{dialog.innerHTML='';pendingCentralImport=null;});
window.addEventListener('beforeunload',event=>{if(dirtyNote()){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',route);
// Clear private DOM immediately when leaving the page or signing out. No offline private cache.
window.addEventListener('pagehide',()=>{routeVersion++;personUi.clear();fieldUi.clear();masterUi.clear();archiveUi.clear();app.innerHTML='';dialog.innerHTML='';currentCentral=null;pendingCentralImport=null;currentRoster=null;pendingRoster=null;currentAdmission=null;currentSession=null;currentScenario=null;editingCharacter=null;currentPlayer=null;currentPlayerRoute=null;});
window.addEventListener('pageshow',e=>{if(e.persisted)route();});
onAuthStateChanged(auth,()=>{mediaUi.clear();updateAccount();route();});


document.addEventListener('change',event=>{if(!event.target.matches('[data-form="admissionProposal"] [name="classId"]'))return;const select=event.target.form.elements.secondaryId;for(const option of select.options)option.disabled=!!event.target.value&&option.value.startsWith(`${event.target.value}-`);if(select.selectedOptions[0]?.disabled)select.value='';});
document.addEventListener('input',event=>{if(!event.target.matches('[data-admission-filter]')||!currentAdmission?.registrations)return;const filter=Object.fromEntries([...app.querySelectorAll('[data-admission-filter]')].map(el=>[el.dataset.admissionFilter,el.value]));app.querySelector('[data-admission-list]').innerHTML=admissionUi.dossierList(currentAdmission,filter);});

document.addEventListener('change',event=>{if(event.target.matches('[data-form="centralCharacter"] [name="profileMode"], [data-form="centralCharacter"] [name="profileClass"], [data-form="centralCharacter"] [name="profileSecondary"]'))syncCentralPlanForm(event.target.form);});
